fn vp_player_submit(game: &crate::game::Game<'_>, player: &crate::game::NativeMobRender<'_>, who: &crate::game::NativePlayerRender<'_>, draw: &mut crate::game::native_block_entity_draw::BlockEntityDraw, drawn: &mut bool) -> ::core::ops::ControlFlow<()> { if crate::game::native_vibe_physics::on_player_submit(game, player, who, draw) { *drawn = true; ::core::ops::ControlFlow::Break(()) } else { ::core::ops::ControlFlow::Continue(()) } }
